-- 10 relaciones SchoolAdmin de seed: los 2 admins originales (admin@, admin2@) mas los 8 nuevos.
-- Cada admin administra exactamente un colegio (UQ_SchoolAdmin_Profile):
--   Sabana (A2000001): admin@, admin3, admin4, admin5
--   Tecnico del Oriente (A2000002): admin2@, admin6, admin7, admin8
--   Giron (A2000003): admin9, admin10
-- Vive en iam-db (no en ms-school-db) porque liquibase-school corre ANTES de liquibase-iam
-- y estas filas referencian perfiles creados en este mismo changelog (FK_SchoolAdmin_Profile).
-- Idempotente: WHERE NOT EXISTS por ProfileId.
INSERT INTO School.SchoolAdmin (Id, SchoolId, ProfileId, Status)
SELECT v.Id, v.SchoolId, v.ProfileId, 'Active'
FROM (VALUES
    ('A5000001-0000-4000-8000-000000000001', 'A2000001-0000-4000-8000-000000000001', 'A0AF22FD-ED0E-4196-A8D1-ADDD9A881267'),
    ('A5000002-0000-4000-8000-000000000002', 'A2000001-0000-4000-8000-000000000001', 'C1000058-0000-4000-8000-000000000058'),
    ('A5000003-0000-4000-8000-000000000003', 'A2000001-0000-4000-8000-000000000001', 'C1000059-0000-4000-8000-000000000059'),
    ('A5000004-0000-4000-8000-000000000004', 'A2000001-0000-4000-8000-000000000001', 'C1000060-0000-4000-8000-000000000060'),
    ('A5000005-0000-4000-8000-000000000005', 'A2000002-0000-4000-8000-000000000002', '387F2C49-5EDC-4E99-9119-3403D56D9159'),
    ('A5000006-0000-4000-8000-000000000006', 'A2000002-0000-4000-8000-000000000002', 'C1000061-0000-4000-8000-000000000061'),
    ('A5000007-0000-4000-8000-000000000007', 'A2000002-0000-4000-8000-000000000002', 'C1000062-0000-4000-8000-000000000062'),
    ('A5000008-0000-4000-8000-000000000008', 'A2000002-0000-4000-8000-000000000002', 'C1000063-0000-4000-8000-000000000063'),
    ('A5000009-0000-4000-8000-000000000009', 'A2000003-0000-4000-8000-000000000003', 'C1000064-0000-4000-8000-000000000064'),
    ('A5000010-0000-4000-8000-000000000010', 'A2000003-0000-4000-8000-000000000003', 'C1000065-0000-4000-8000-000000000065')
) AS v (Id, SchoolId, ProfileId)
WHERE NOT EXISTS (SELECT 1 FROM School.SchoolAdmin sa WHERE sa.ProfileId = v.ProfileId);
